"""Calm, explicit what-if planning. No implicit bank access or model training."""
CASHFLOW_CSS = r"""
.runway-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0}.runway-grid label{display:grid;gap:7px;font-size:13px}.runway-grid input{min-height:44px;padding:10px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--ink);font:inherit;width:100%}.runway-events{display:grid;grid-template-columns:1fr 1fr;gap:16px}.runway-row{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;margin:8px 0}.runway-row input{width:100%;min-width:0;min-height:40px;padding:8px;border:1px solid var(--line);border-radius:10px;background:var(--panel);color:var(--ink)}.runway-row button{border:1px solid var(--line);border-radius:10px;background:var(--panel2);color:var(--ink);cursor:pointer}.runway-status{padding:16px;border-radius:16px;background:var(--panel2);border:1px solid var(--line);margin:16px 0}.runway-status[data-tone=warning]{border-color:#c39138}.runway-status[data-tone=shortfall]{border-color:#cf6577}.runway-chart{width:100%;height:auto;max-height:210px;margin:14px 0}.runway-help{font-size:13px;color:var(--muted);line-height:1.6}.runway-consent{display:flex;align-items:flex-start;gap:9px;font-size:13px;line-height:1.6;margin:15px 0}.runway-consent input{margin-top:5px}.runway-result dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.runway-result dt{font-size:12px;color:var(--muted)}.runway-result dd{font-size:23px;font-weight:750;margin:8px 0}@media(max-width:700px){.runway-grid,.runway-events{grid-template-columns:1fr 1fr}.runway-result dl{grid-template-columns:1fr}.runway-row{grid-template-columns:1fr}.runway-events{grid-template-columns:1fr}}
"""

CASHFLOW_JS = r"""
    {
      const runway=element('section',null,'money-section');runway.id='friday-runway';runway.setAttribute('aria-label','Money runway');
      runway.append(element('h2','Money runway. Look ahead.'),element('p','See whether your entered cash, bills and spending could leave a gap before income arrives. This is a scenario—not a bank prediction.','runway-help'));
      const localDate=offset=>{const date=new Date();date.setDate(date.getDate()+offset);return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');};
      const form=element('form');const grid=element('div',null,'runway-grid');
      function field(label,type,value=''){const wrapper=element('label',label);const input=element('input');input.type=type;input.value=value;input.setAttribute('aria-label',label);if(type==='text'){input.inputMode='decimal';input.placeholder='INR rupees';input.maxLength=16;}wrapper.append(input);grid.append(wrapper);return input;}
      const cash=field('Available cash (INR)','text'),floor=field('Keep this buffer (INR)','text','2000'),spend=field('Daily variable spending (INR)','text'),start=field('Scenario start date','date',localDate(0)),horizon=field('Days to look ahead','number','30'),delay=field('What if income is late? (days)','number','7');horizon.min='1';horizon.max='90';delay.min='0';delay.max='30';form.append(grid);
      const events=element('div',null,'runway-events');const incomes=element('section'),bills=element('section');incomes.append(element('h3','Expected income'));bills.append(element('h3','Known bills'));events.append(incomes,bills);form.append(events);
      function addRow(parent,kind,date='',amount=''){if(parent.querySelectorAll('.runway-row').length>=10){toast('Keep this plan to ten entries of each type.');return;}const row=element('div',null,'runway-row');const day=element('input');day.type='date';day.value=date;day.setAttribute('aria-label',kind+' date');const money=element('input');money.type='text';money.inputMode='decimal';money.maxLength=16;money.value=amount;money.placeholder='Amount (INR)';money.setAttribute('aria-label',kind+' amount (INR)');const remove=element('button','Remove');remove.type='button';remove.setAttribute('aria-label','Remove '+kind+' entry');remove.addEventListener('click',()=>{row.remove();form.dispatchEvent(new Event('input'));});row.append(day,money,remove);parent.append(row);}
      const addIncome=element('button','Add income','planner'),addBill=element('button','Add bill','planner');addIncome.type=addBill.type='button';addIncome.addEventListener('click',()=>{addRow(incomes,'Income');form.dispatchEvent(new Event('input'));});addBill.addEventListener('click',()=>{addRow(bills,'Bill');form.dispatchEvent(new Event('input'));});incomes.append(addIncome);bills.append(addBill);addRow(incomes,'Income');addRow(bills,'Bill');
      form.append(element('p','Daily spending excludes the bills listed here. Expected income is not guaranteed. Payments and spending are deducted before same-day income.','runway-help'));
      const save=element('input');save.type='checkbox';save.id='runway-save';const consent=element('label',null,'runway-consent');consent.append(save,element('span','Save only this latest plan and calculator result in my private Friday workspace. No raw statement or model training. Review cleanup will remove it.'));form.append(consent);
      const calculate=element('button','Check my runway','planner');calculate.type='submit';const loadExample=element('button','Try an editable example','planner');loadExample.type='button';const reopen=element('button','Load my saved plan','planner');reopen.type='button';const controls=element('div',null,'obligation-actions');controls.append(calculate,loadExample,reopen);form.append(controls,element('p','Check sends these assumptions to the Friday server for calculation. Gemini sees them only with separate chat consent. No money moves.','runway-help'));
      const status=element('p','Enter a plan or try the labelled example. No bank or SMS source is connected.','runway-help');status.setAttribute('role','status');const output=element('div',null,'runway-result');runway.append(form,status,output);moneyWorkspace.prepend(runway);
      const shortcut=element('button','Check my money runway','planner');shortcut.type='button';shortcut.addEventListener('click',()=>{show('money');runway.scrollIntoView({block:'start'});cash.focus();});home.querySelector('.buddy-actions')?.append(shortcut);
      function minor(value){const text=value.trim();if(!/^[0-9]{1,8}(\.[0-9]{1,2})?$/.test(text))throw new Error('Use non-negative INR rupees with up to two decimals.');const [whole,fraction='']=text.split('.');return Number(whole)*100+Number(fraction.padEnd(2,'0'));}
      function rows(parent){return [...parent.querySelectorAll('.runway-row')].flatMap(row=>{const [day,money]=row.querySelectorAll('input');if(!day.value&&!money.value.trim())return [];if(!day.value||!money.value.trim())throw new Error('Give each income/bill both a date and amount, or remove it.');return [{date:day.value,amount_minor:minor(money.value)}];});}
      function negativeMoney(value){return (value<0?'−':'')+workspaceMoney(Math.abs(value));}
      function chart(result){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 700 170');svg.setAttribute('role','img');svg.setAttribute('aria-label','Entered cash-flow scenario: purple before-income cash; amber if income is delayed. Not bank data.');svg.classList.add('runway-chart');const all=[...result.baseline.timeline,...result.delayed_income.timeline].map(point=>point.before_income_minor);const low=Math.min(0,result.reserve_minor,...all),high=Math.max(result.reserve_minor,...all,1);const y=value=>140-(value-low)/(high-low)*115;const line=document.createElementNS(svg.namespaceURI,'line');line.setAttribute('x1','15');line.setAttribute('x2','685');line.setAttribute('y1',y(result.reserve_minor));line.setAttribute('y2',y(result.reserve_minor));line.setAttribute('stroke','#a8a4b5');line.setAttribute('stroke-dasharray','5 5');svg.append(line);[[result.baseline.timeline,'#7975d5'],[result.delayed_income.timeline,'#b87828']].forEach(([points,color])=>{const path=document.createElementNS(svg.namespaceURI,'polyline');path.setAttribute('points',points.map((point,index)=>(15+index/Math.max(1,points.length-1)*670)+','+y(point.before_income_minor)).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke',color);path.setAttribute('stroke-width','3');svg.append(path);});return svg;}
      function render(data){if(data.scope!=='USER_SUPPLIED_CASHFLOW_SCENARIO'||data.money_moved!==false||data.payment_authorized!==false||data.ai_called!==false||data.bank_connected!==false)throw new Error('Unexpected forecast authority.');output.replaceChildren();const notice=element('section',null,'runway-status');notice.dataset.tone=data.baseline.first_cash_shortfall?'shortfall':data.baseline.first_buffer_breach?'warning':'neutral';const heading=data.baseline.fixed_commitments_exceed_buffer?'Known commitments alone exceed your chosen buffer.':data.baseline.first_cash_shortfall?'This entered plan could run short.':data.baseline.first_buffer_breach?'Your buffer could get squeezed.':'No gap in this entered scenario.';notice.append(element('h3',heading),element('p',data.baseline.first_buffer_breach?'First projected buffer dip: '+data.baseline.first_buffer_breach+'. If assumptions change, this date changes.':'This does not guarantee affordability or cover missing bills/income.'));output.append(notice);const facts=element('dl');[['Current planned daily spending',data.daily_spend_minor],['Calculated daily cap for this plan',data.baseline.safe_daily_spend_minor],['Cap if income is '+data.income_delay_days+' days late',data.delayed_income.safe_daily_spend_minor]].forEach(([label,value])=>{const box=element('div');box.append(element('dt',label),element('dd',workspaceMoney(value)));facts.append(box);});output.append(facts,chart(data),element('p','Purple: baseline · amber: delayed income · dashed: chosen buffer. Lines show cash before expected income each day.','runway-help'));if(data.baseline.fixed_commitments_exceed_buffer)output.append(element('p','Reducing discretionary spending alone cannot preserve this buffer. Review the entered dates/amounts and essential obligations; this is not advice to skip bills or take a loan.','runway-help'));const detail=element('details');detail.append(element('summary','Numbers and assumptions'));detail.append(element('p','Expected income: '+workspaceMoney(data.expected_income_total_minor)+' · listed bills: '+workspaceMoney(data.committed_bills_total_minor)+' · projected closing cash: '+negativeMoney(data.baseline.closing_cash_minor)));data.limits.forEach(text=>detail.append(element('p',text)));output.append(detail);const ask=element('button','Ask Friday about this plan','planner');ask.type='button';ask.addEventListener('click',()=>{if(!data.saved_to_workspace){toast('Save the plan first if you want to share its summary with Gemini.');save.focus();return;}show('home');const consent=$('friday-chat-cashflow');consent.focus();$('home-command').value='Explain my saved cash-flow scenario and the one practical next step. Use the calculator results, discuss late income, and do not move money or guarantee future balances.';$('home-command').focus();toast('Question ready. Choose saved cash-flow sharing and Ask Friday to send it to Gemini.');});output.append(ask);status.textContent=data.saved_to_workspace?'Plan saved privately. Calculation made no model call or payment.':'Calculated without saving. No model call or payment.';}
      let busy=false,runwayGeneration=0;async function operation(fn){if(busy)return;busy=true;form.setAttribute('aria-busy','true');const generation=runwayGeneration;output.replaceChildren();form.querySelectorAll('button,input').forEach(control=>control.disabled=true);status.textContent='Checking entered assumptions. No model call or payment.';try{await fn(generation);}catch(error){if(generation===runwayGeneration)status.textContent='Plan unavailable: '+error.message+' No payment or success is assumed.';}finally{busy=false;form.setAttribute('aria-busy','false');form.querySelectorAll('button,input').forEach(control=>control.disabled=false);}}
      form.addEventListener('input',()=>{if(!busy){runwayGeneration++;output.replaceChildren();status.textContent='Plan changed. Check again to calculate these assumptions.';}});
      form.addEventListener('submit',event=>{event.preventDefault();operation(async(generation)=>{const body={as_of:start.value,horizon_days:Number(horizon.value),starting_cash_minor:minor(cash.value),reserve_minor:minor(floor.value),daily_spend_minor:minor(spend.value),expected_income:rows(incomes),committed_bills:rows(bills),income_delay_days:Number(delay.value),save_to_workspace:save.checked};const data=await jsonRequest('/api/friday/cashflow','POST',body);if(generation!==runwayGeneration)return;render(data);if(data.saved_to_workspace)document.dispatchEvent(new CustomEvent('friday:cashflow-updated'));});});
      function loadInputs(input){cash.value=String(input.starting_cash_minor/100);floor.value=String(input.reserve_minor/100);spend.value=String(input.daily_spend_minor/100);start.value=input.as_of;horizon.value=String(input.horizon_days);delay.value=String(input.income_delay_days);incomes.querySelectorAll('.runway-row').forEach(row=>row.remove());bills.querySelectorAll('.runway-row').forEach(row=>row.remove());input.expected_income.forEach(row=>addRow(incomes,'Income',row.date,String(row.amount_minor/100)));input.committed_bills.forEach(row=>addRow(bills,'Bill',row.date,String(row.amount_minor/100)));}
      loadExample.addEventListener('click',()=>{loadInputs({starting_cash_minor:800000,reserve_minor:200000,daily_spend_minor:40000,as_of:localDate(0),horizon_days:30,income_delay_days:7,expected_income:[{date:localDate(14),amount_minor:1800000}],committed_bills:[{date:localDate(7),amount_minor:450000}]});save.checked=false;output.replaceChildren();status.textContent='Artificial example loaded for editing. Nothing sent, saved or calculated yet.';});
      reopen.addEventListener('click',()=>operation(async(generation)=>{const data=await jsonRequest('/api/friday/cashflow');if(generation!==runwayGeneration)return;if(!data.snapshot){status.textContent='No saved cash-flow plan. Enter a snapshot; Friday cannot read your bank.';return;}loadInputs(data.snapshot.inputs);save.checked=false;render(data.snapshot.result);status.textContent='Saved scenario from '+data.snapshot.created_at.slice(0,10)+'. Update cash and dates before relying on it.';}));
      document.addEventListener('friday:cashflow-cleared',()=>{runwayGeneration++;output.replaceChildren();save.checked=false;cash.value='';spend.value='';incomes.querySelectorAll('.runway-row').forEach(row=>row.remove());bills.querySelectorAll('.runway-row').forEach(row=>row.remove());addRow(incomes,'Income');addRow(bills,'Bill');status.textContent='Saved cash-flow snapshot cleared. No statement or balance is assumed.';});
    }
"""
